/**
 * POST /api/files/:fileId/rematch: what matching a file on MusicBrainz again did.
 */
@Serializable(with = RematchResult.ByTag::class)
public sealed interface RematchResult {
    public val kind: String

    @Serializable
    public data class Folder(
        /**
         * What became of the file: matched (auto), waiting for review, or left with its own tags.
         */
        public val state: State,
        /**
         * The song the file belongs to now (it changes when a match gives it its real MusicBrainz id).
         */
        public val trackId: Int? = null,
        @EncodeDefault override val kind: String = "folder",
    ) : RematchResult {
        @Serializable
        @JvmInline
        public value class State(public val value: String) {
            /** One of the values this version of the app knows. */
            public val isKnown: Boolean get() = this in entries

            override fun toString(): String = value

            public companion object {
                public val Auto: State = State("auto")
                public val Manual: State = State("manual")
                public val Review: State = State("review")
                public val Unmatched: State = State("unmatched")
                public val Ignored: State = State("ignored")
                public val entries: List<State> = listOf(Auto, Manual, Review, Unmatched, Ignored)
            }
        }
    }

    @Serializable
    public data class Lidarr(
        /**
         * Lidarr is refreshing the artist from MusicBrainz; Playarr picks the changes up on its next sync.
         */
        public val message: String,
        @EncodeDefault override val kind: String = "lidarr",
    ) : RematchResult

    /** A `kind` this version of the app doesn't know yet. */
    @Serializable
    public data class Unknown(override val kind: String) : RematchResult

    /** Picks the variant by `kind`. */
    public object ByTag : JsonContentPolymorphicSerializer<RematchResult>(RematchResult::class) {
        override fun selectDeserializer(element: JsonElement): DeserializationStrategy<RematchResult> =
            when ((element as? JsonObject)?.get("kind")?.let { (it as? JsonPrimitive)?.contentOrNull }) {
                "folder" -> Folder.serializer()
                "lidarr" -> Lidarr.serializer()
                else -> Unknown.serializer()
            }
    }
}

/**
 * How far a transition being made has got: waiting its turn (behind `ahead` others), decoding the two songs around the mix, mixing them, saving the file, then (for an MP3 next song) saving the rest of it. `done` is the whole job's share done, 0–1, the steps weighted by about how long each takes.
