/**
 * POST /api/transitions: the file to play (ready), still rendering (pending, ask again), better played straight on, or not possible (no mix map yet, say).
 */
@Serializable(with = TransitionAnswer.ByTag::class)
public sealed interface TransitionAnswer {
    public val status: String

    @Serializable
    public data class Ready(
        public val plan: TransitionPlan,
        public val url: String,
        public val continuationUrl: String? = null,
        /**
         * Seconds of B after the transition in its file (see TRANSITION_TAIL_SECONDS); none in older files.
         */
        public val tail: Double? = null,
        /**
         * Seconds of A before the transition in its file: the file starts at plan.aStart − lead. None in older files.
         */
        public val lead: Double? = null,
        /**
         * The songs' gains (dB) made into the audio (and B's remainder), when they were asked for.
         */
        public val levels: Levels? = null,
        @EncodeDefault override val status: String = "ready",
    ) : TransitionAnswer {
        @Serializable
        public data class Levels(
            public val a: Double,
            public val b: Double,
        )
    }

    @Serializable
    public data class Pending(
        public val plan: TransitionPlan,
        public val render: RenderProgress? = null,
        @EncodeDefault override val status: String = "pending",
    ) : TransitionAnswer

    @Serializable
    public data class Straight(
        public val plan: TransitionPlan,
        @EncodeDefault override val status: String = "straight",
    ) : TransitionAnswer

    @Serializable
    public data class Unavailable(
        public val reason: String,
        @EncodeDefault override val status: String = "unavailable",
    ) : TransitionAnswer

    /** A `status` this version of the app doesn't know yet. */
    @Serializable
    public data class Unknown(override val status: String) : TransitionAnswer

    /** Picks the variant by `status`. */
    public object ByTag : JsonContentPolymorphicSerializer<TransitionAnswer>(TransitionAnswer::class) {
        override fun selectDeserializer(element: JsonElement): DeserializationStrategy<TransitionAnswer> =
            when ((element as? JsonObject)?.get("status")?.let { (it as? JsonPrimitive)?.contentOrNull }) {
                "ready" -> Ready.serializer()
                "pending" -> Pending.serializer()
                "straight" -> Straight.serializer()
                "unavailable" -> Unavailable.serializer()
                else -> Unknown.serializer()
            }
    }
}

@Serializable
public data class TransitionPlan(
    public val style: TransitionStyle,
    /**
     * Where in A the transition starts (A plays normally until here).
     */
    public val aStart: Double,
    /**
     * Where in B the transition starts.
     */
    public val bStart: Double,
    /**
     * Seconds of transition output. It can run past A's end (a long blend's ease-back is B alone): A's gain is 0 by then, so the renderer treats A as silent past its end.
     */
    public val length: Double,
    /**
     * Where in B normal playback resumes after the transition.
     */
    public val bResume: Double,
    /**
     * Seconds into the transition where the listener hears B take over (lock screen switches here).
     */
    public val switchAt: Double,
    /**
     * B's playback rate over the transition (1 = its own tempo), per point; A always plays at 1.
     */
    public val bRate: Automation,
    public val aGain: Automation,
    public val bGain: Automation,
    /**
     * Low-shelf gain in dB on each side (0 = flat, −24 = bass gone): the bass swap.
     */
    public val aLowDb: Automation,
    public val bLowDb: Automation,
    /**
     * High-pass cutoff in Hz on A (20 = off): the quick-mix sweep.
     */
    public val aHighPassHz: Automation,
    /**
     * Why this style: for the transition view and logs.
     */
    public val reason: String,
    /**
     * Beats of A in the move, for the transition view: the overlap for a long blend (not B's ease-back after it), the lead-in up to the landing (8 or 4) for a quick mix, cuts included; 0 for a fade or straight on.
     */
    public val beats: Double,
)

@Serializable
@JvmInline
public value class TransitionStyle(public val value: String) {
    /** One of the values this version of the app knows. */
